    "slug": "the-potbelly-hauz-khas",
    "short_description": "Acclaimed regional rooftop kitchen showcasing authentic Bihari cuisine, litti chokha, and sattu parathas.",
    "long_description": "Perched on the top floor of Hauz Khas Market with sweeping views over the surrounding treetops, The Potbelly is a nationally celebrated culinary gem run by a mother-daughter duo. It brings the rich, rustic culinary heritage of Bihar into a chic bohemian dining space with colorful tapestries and bamboo lamps. Known especially for pure desi ghee preparations, their vegetarian spread features litti chokha, sattu parathas, and spiced chana ghughni.",
