    "slug": "living-room-by-kalsang",
    "short_description": "Bohemian rooftop cafe by the famous Kalsang family, serving Korean ramyeon, bubble tea, and cheese corndogs.",
    "long_description": "Living Room by Kalsang represents the younger, modern pan-Asian evolution of Majnu Ka Tilla's dining landscape. Set on the 5th floor of Building 30 in New Aruna Colony, this chic rooftop combines lush potted greenery, cooling mist fans, cane wicker furniture, and floor-level low seating cushions. Frequented heavily by K-pop and K-drama enthusiasts from Delhi University, the kitchen delivers authentic Korean fusion staples including kimchi bokkeumbap, bubbling Shin Ramyeon hot pots, crispy cheese corndogs, and specialty boba teas.",
