    "name": "Romeo and Juliet Cafe",
    "slug": "romeo-and-juliet-cafe",
    "short_description": "Expansive romantic rooftop with sweeping Signature Bridge views, private cabanas, and spicy devil momos.",
    "long_description": "Boasting the title of the largest rooftop terrace in Majnu Ka Tilla, Romeo and Juliet Cafe spans the 5th floor of Tara House (Wing A). Decorated with glowing neon slogans, romantic fairy lights, and curtained wooden cabanas, it is widely celebrated as the primary date-night and celebration destination in North Delhi. The establishment features an open-air deck as well as an air-conditioned lounge, catering to large groups of DU students. The kitchen offers a broad continental, pan-Asian, and Tibetan menu highlighted by spicy devil jhol momos, wood-fired pizzas, udon noodle bowls, and crafted mocktails.",
