    "name": "MACHEN LA Tibet Kitchen",
    "slug": "machen-la-tibet-kitchen",
    "short_description": "Monastery-inspired Tibetan cultural restaurant famed for authentic morning buffet breakfasts, gyuma, and herbal stews.",
    "long_description": "Nestled near Sopa Kitchen inside Rabsel House, MACHEN LA Tibet Kitchen is celebrated for its deep devotion to traditional Tibetan monastic culture and authentic cuisine. The interiors are decorated with Tibetan murals, thangkas, and hand-carved cedar furniture, creating an unhurried sanctuary away from the hustle of the market. Renowned among community elders and savvy food scouts, Machen La serves an affordable morning Tibetan breakfast buffet alongside specialty dishes such as vegetable gyuma, tingmo bread platters, handmade sushi rolls, and herbal spiced soups.",
