    "short_description": "Surreal black-and-white comic book illusion cafe in MKT serving crispy thin-crust pizzas, pasta, and coolers.",
    "long_description": "Delhi 2D Cafe transports diners straight into a real-life graphic novel through its bespoke monochrome comic book aesthetic, where every chair, table, pillar, and mural is drawn in black outlines on white backgrounds. Located on the 2nd floor of House No. 7 in New Aruna Colony, it is an Instagram sensation and an exceptionally popular hangout spot for students and visiting creators. The menu matches its playful visuals with loaded cheesy pizzas, crispy mozzarella sticks, peri-peri potato wedges, Korean strawberry milk, and thick chocolate shakes.",
